INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2449549, 337336, 32254, '<td valign="top">Great angle and exposure, well done capture.</td>', 'Great angle and exposure, well done capture.', '2006-05-23 11:47:55.000000', NULL, 1),
(2449550, 336767, 50034, '<td valign="top">(James 4:14 KJV)  "Whereas ye know not what shall be on the morrow. For what is your life? It is even a vapour, that appeareth for a little time, and then vanisheth away."<br/> <br/>This is another great illustration I could use in PowerPoint.  Would you give me your permission?</td>', '(James 4:14 KJV)  "Whereas ye know not what shall be on the morrow. For what is your life? It is even a vapour, that appeareth for a little time, and then vanisheth away." This is another great illustration I could use in PowerPoint.  Would you give me your permission?', '2006-05-23 11:49:20.000000', NULL, 1),
(2449553, 337416, 50034, '<td valign="top">Hmmmm.  Like a "bike out Hell" maybe?  ;)</td>', 'Hmmmm.  Like a "bike out Hell" maybe?  ;)', '2006-05-23 11:50:42.000000', NULL, 1),
(2449555, 337336, 50034, '<td valign="top">Stunning!!!!   Breath-Taking!!!!  This deserves two 10s!!!!</td>', 'Stunning!!!!   Breath-Taking!!!!  This deserves two 10s!!!!', '2006-05-23 11:52:08.000000', NULL, 1),
(2449573, 337501, 50034, '<td valign="top">For success as a photographer, children are always the "Hot Ticket!"  <br/>   Of course, this also looks like the "Growth Stages of Childhood," even though my mind tells me that these three are sisters.  <br/>   The youngest is upset that "They splashed water on me!"  The middle sister it''s pretty funny and "maybe we got away with it."  Finally, the eldest is looking to see if Mom is looking, how Mom is reacting, and "then I''ll decide whether or no to laugh!"</td>', 'For success as a photographer, children are always the "Hot Ticket!"     Of course, this also looks like the "Growth Stages of Childhood," even though my mind tells me that these three are sisters.     The youngest is upset that "They splashed water on me!"  The middle sister it''s pretty funny and "maybe we got away with it."  Finally, the eldest is looking to see if Mom is looking, how Mom is reacting, and "then I''ll decide whether or no to laugh!"', '2006-05-23 12:01:44.000000', NULL, 1),
(2449576, 335862, 50034, '<td valign="top">This is what Sibelius said after performing one of his piano concerti for the first time!</td>', 'This is what Sibelius said after performing one of his piano concerti for the first time!', '2006-05-23 12:04:58.000000', NULL, 1),
(2449580, 337441, 50034, '<td valign="top">Playing "Spin the Bottle" would get me a little "heated", too.</td>', 'Playing "Spin the Bottle" would get me a little "heated", too.', '2006-05-23 12:06:49.000000', NULL, 1),
(2449583, 336719, 50034, '<td valign="top">You Know It!!!!!!!   De Veras,...Verdad,...De Cierto!!!!</td>', 'You Know It!!!!!!!   De Veras,...Verdad,...De Cierto!!!!', '2006-05-23 12:08:40.000000', NULL, 1),
(2449603, 337361, 50034, '<td valign="top">I love the allusion &amp; the backlighting &amp; apparently some PS saturation as well.  Great Artist!<br/>   The face of the sunflower distracts me a little because it''s dark, wispy, and almost "out-of-character."  However, muted yellows would have supported the concept while not detracting from the subject.<br/>   Finally, as I recall satellite images that I''ve seen of solar flares, I vaguely remember the surface of the sun having many black areas.  If that''s true then you "nailed it."  As I said, "Great Artist!"  Great photographer as well.   :)</td>', 'I love the allusion & the backlighting & apparently some PS saturation as well.  Great Artist!   The face of the sunflower distracts me a little because it''s dark, wispy, and almost "out-of-character."  However, muted yellows would have supported the concept while not detracting from the subject.   Finally, as I recall satellite images that I''ve seen of solar flares, I vaguely remember the surface of the sun having many black areas.  If that''s true then you "nailed it."  As I said, "Great Artist!"  Great photographer as well.   :)', '2006-05-23 12:21:48.000000', NULL, 1),
(2449613, 337487, 50034, '<td valign="top">This brings back memories of my high school science classes.  According to the book &amp; the teacher, "A blue flame is hotter always hotter than a red flame!"       COOL!!!!!!!       ;)</td>', 'This brings back memories of my high school science classes.  According to the book & the teacher, "A blue flame is hotter always hotter than a red flame!"       COOL!!!!!!!       ;)', '2006-05-23 12:25:13.000000', NULL, 1),
(2449615, 337326, 3569, '<td valign="top">Beautiful shot, but hard to see heat from the shot.</td>', 'Beautiful shot, but hard to see heat from the shot.', '2006-05-23 12:25:29.000000', NULL, 1),
(2449620, 337506, 48389, '<td valign="top">Great title and original idea</td>', 'Great title and original idea', '2006-05-23 12:26:52.000000', NULL, 1),
(2449627, 337416, 48389, '<td valign="top">Clever idea</td>', 'Clever idea', '2006-05-23 12:27:39.000000', NULL, 1),
(2449636, 336985, 48389, '<td valign="top">Really like this good composition and detail</td>', 'Really like this good composition and detail', '2006-05-23 12:28:49.000000', NULL, 1),
(2449644, 337426, 48389, '<td valign="top">Very neat idea, well composed and executed</td>', 'Very neat idea, well composed and executed', '2006-05-23 12:30:01.000000', NULL, 1),
(2449645, 337392, 50034, '<td valign="top">Great capture of one of the first split-seconds of a match flame!  I hope you didn''t have to go through a whole box to get this one, but it was certainly worth all your great effort!<br/>   I would love to gain your permission to use this in PowerPoint!</td>', 'Great capture of one of the first split-seconds of a match flame!  I hope you didn''t have to go through a whole box to get this one, but it was certainly worth all your great effort!   I would love to gain your permission to use this in PowerPoint!', '2006-05-23 12:30:19.000000', NULL, 1),
(2449646, 337415, 50034, '<td valign="top">Wonderful!</td>', 'Wonderful!', '2006-05-23 12:30:49.000000', NULL, 1),
(2449654, 335862, 48389, '<td valign="top">"No one was injured in the taking of this entry"? I hope? :) Nice idea, good detail in the flame and the expression is great</td>', '"No one was injured in the taking of this entry"? I hope? :) Nice idea, good detail in the flame and the expression is great', '2006-05-23 12:32:17.000000', NULL, 1),
(2449660, 336973, 48389, '<td valign="top">nice, different idea but the ''flame'' is a bit too subtle for me<br/><br/><i>Message edited by author 2006-06-08 15:30:31.</i></td>', 'nice, different idea but the ''flame'' is a bit too subtle for me', '2006-05-23 12:33:35.000000', '2006-06-08 16:30:31.000000', 1),
(2449665, 337327, 48389, '<td valign="top">Great composition and colours!</td>', 'Great composition and colours!', '2006-05-23 12:34:44.000000', NULL, 1),
(2449669, 337277, 50034, '<td valign="top">Yep!  That''s exactly what dry ice feels like!   )O</td>', 'Yep!  That''s exactly what dry ice feels like!   )O', '2006-05-23 12:35:10.000000', NULL, 1),
(2449770, 337392, 52549, '<td valign="top">Very interesting perspective. You can really feel the heat. Excellent capture.</td>', 'Very interesting perspective. You can really feel the heat. Excellent capture.', '2006-05-23 13:12:11.000000', NULL, 1),
(2449782, 337322, 59196, '<td valign="top">beautiful!!</td>', 'beautiful!!', '2006-05-23 13:17:57.000000', NULL, 1),
(2449801, 337336, 40490, '<td valign="top">This shot is awesome; wonderful perspective, fantastic colors, this image is fantastic, how''d you get the colors like that!?</td>', 'This shot is awesome; wonderful perspective, fantastic colors, this image is fantastic, how''d you get the colors like that!?', '2006-05-23 13:27:43.000000', NULL, 1),
(2449885, 336741, 32754, '<td valign="top">great image..lovely color, tone, composition...</td>', 'great image..lovely color, tone, composition...', '2006-05-23 13:59:48.000000', NULL, 1),
(2449907, 336804, 34396, '<td valign="top">I like the crisp focus on the matches.  The cropping seems a bit close for my eye, would have liked a bit more room on either side.  Additionally, I wonder if a faster shutter would have given more impact to the flame.</td>', 'I like the crisp focus on the matches.  The cropping seems a bit close for my eye, would have liked a bit more room on either side.  Additionally, I wonder if a faster shutter would have given more impact to the flame.', '2006-05-23 14:15:53.000000', NULL, 1),
(2449912, 337277, 34396, '<td valign="top">Interesting shot.  I like the blend of yellow and blue here.  Shot seems a bit fuzzy, cant tell if is focus or slow shutter related.  Nice</td>', 'Interesting shot.  I like the blend of yellow and blue here.  Shot seems a bit fuzzy, cant tell if is focus or slow shutter related.  Nice', '2006-05-23 14:18:09.000000', NULL, 1),
(2449922, 337244, 34396, '<td valign="top">Nice vivid image.  I don''t particulary like the flame position in the photo.  I think if the candle had been placed to the right front of the peppers, you would have had some nice reflections playing on the front of the peppers.  Overall though a nice shot.</td>', 'Nice vivid image.  I don''t particulary like the flame position in the photo.  I think if the candle had been placed to the right front of the peppers, you would have had some nice reflections playing on the front of the peppers.  Overall though a nice shot.', '2006-05-23 14:20:48.000000', NULL, 1),
(2449938, 337233, 34396, '<td valign="top">Hmmm, a very clear photo of a dial that idicates "no heat".  Now, if the needle was at 320F with a little steam escaping.....</td>', 'Hmmm, a very clear photo of a dial that idicates "no heat".  Now, if the needle was at 320F with a little steam escaping.....', '2006-05-23 14:25:01.000000', NULL, 1),
(2449946, 337158, 34396, '<td valign="top">Nice shot, I would have liked to have seen the entire burner without cropping the sides off, but I like the contrast of the red against the deep black.</td>', 'Nice shot, I would have liked to have seen the entire burner without cropping the sides off, but I like the contrast of the red against the deep black.', '2006-05-23 14:26:16.000000', NULL, 1),
(2449961, 336440, 42100, '<td valign="top">Very nicely done Manuel, nice tones as always.  The refelction is an interesting touch.</td>', 'Very nicely done Manuel, nice tones as always.  The refelction is an interesting touch.', '2006-05-23 14:30:06.000000', NULL, 1),
(2449963, 337094, 34396, '<td valign="top">I think this photo captures the Hot/Cold feeling.  The cluttered background distracts from the overall effect for me.</td>', 'I think this photo captures the Hot/Cold feeling.  The cluttered background distracts from the overall effect for me.', '2006-05-23 14:30:12.000000', NULL, 1),
(2449978, 337493, 34396, '<td valign="top">A beautiful shot.  An interesting take on the challenge.  A term that is commonly used in baseball, but rarely "visualized" I think.  Hey Mikey, I think I like it!</td>', 'A beautiful shot.  An interesting take on the challenge.  A term that is commonly used in baseball, but rarely "visualized" I think.  Hey Mikey, I think I like it!', '2006-05-23 14:33:29.000000', NULL, 1),
(2449992, 337315, 34396, '<td valign="top">Nice capture.  And someone who knows their meteorology!  Those windmills are a bit distracting, but then you probably didn''t have time to move them before the shot!  Good job.</td>', 'Nice capture.  And someone who knows their meteorology!  Those windmills are a bit distracting, but then you probably didn''t have time to move them before the shot!  Good job.', '2006-05-23 14:36:46.000000', NULL, 1),
(2449998, 337118, 34396, '<td valign="top">WOW!  This is a cool shot.  I really like the glossy surface of the chocolate.  The lighting seems a bit harsh near the top, but overall very nice!</td>', 'WOW!  This is a cool shot.  I really like the glossy surface of the chocolate.  The lighting seems a bit harsh near the top, but overall very nice!', '2006-05-23 14:38:24.000000', NULL, 1),
(2450010, 337503, 34396, '<td valign="top">Cool Shot.  (Or should I say "Hot Shot")  I like the individual drops of water in the shot.  Very nice.</td>', 'Cool Shot.  (Or should I say "Hot Shot")  I like the individual drops of water in the shot.  Very nice.', '2006-05-23 14:42:47.000000', NULL, 1),
(2450016, 336841, 34396, '<td valign="top">Hot!  Very clear photo.  I''m not crazy about the border, but the photo is very nice.</td>', 'Hot!  Very clear photo.  I''m not crazy about the border, but the photo is very nice.', '2006-05-23 14:46:10.000000', NULL, 1),
(2450026, 337389, 34396, '<td valign="top">A good concept, but I think the photo is a bit "busy"  The empty pans on the stove distract the eye from the subject.</td>', 'A good concept, but I think the photo is a bit "busy"  The empty pans on the stove distract the eye from the subject.', '2006-05-23 14:49:59.000000', NULL, 1),
(2450028, 335862, 34396, '<td valign="top">LOL, the expression on the subject''s face makes this photo!  I like the use of the black background which makes the subject jump out at you.  The crisp focus and lighting are excellent!</td>', 'LOL, the expression on the subject''s face makes this photo!  I like the use of the black background which makes the subject jump out at you.  The crisp focus and lighting are excellent!', '2006-05-23 14:52:21.000000', NULL, 1),
(2450031, 337046, 34396, '<td valign="top">Nice!  I like the lighting and image here.  The cropping seems a bit tight at the top.</td>', 'Nice!  I like the lighting and image here.  The cropping seems a bit tight at the top.', '2006-05-23 14:53:49.000000', NULL, 1),
(2450032, 337236, 34134, '<td valign="top">Very well done.</td>', 'Very well done.', '2006-05-23 14:54:16.000000', NULL, 1),
(2450037, 337228, 34396, '<td valign="top">Nice take on the challenge.  Although it looks like you might have a small hill on the right, the horizon looks a bit slanted.  I would have rotated slightly clockwize to minimize the effect.  The egg looks very natural in this setting, (doesn''t look staged)  Nice job.</td>', 'Nice take on the challenge.  Although it looks like you might have a small hill on the right, the horizon looks a bit slanted.  I would have rotated slightly clockwize to minimize the effect.  The egg looks very natural in this setting, (doesn''t look staged)  Nice job.', '2006-05-23 14:56:59.000000', NULL, 1),
(2450046, 336079, 34396, '<td valign="top">This could have been a great photo. The background is a bit clutterd, which distracts from the overall effect.  The angle seems a bit "extreme" to me, which may have been your intent, but I found to also be distracting.  Very cool effect.</td>', 'This could have been a great photo. The background is a bit clutterd, which distracts from the overall effect.  The angle seems a bit "extreme" to me, which may have been your intent, but I found to also be distracting.  Very cool effect.', '2006-05-23 15:04:45.000000', NULL, 1),
(2450083, 337421, 52939, '<td valign="top">Nice length to the flames.  Detail to the laces are still nice and clear I like that - Well done.  <br/> <br/>Was the ball dropped vertically and then the picture rotated?</td>', 'Nice length to the flames.  Detail to the laces are still nice and clear I like that - Well done.   Was the ball dropped vertically and then the picture rotated?', '2006-05-23 15:20:16.000000', NULL, 1),
(2450141, 337046, 54702, '<td valign="top">The shape of the flame is beautiful.</td>', 'The shape of the flame is beautiful.', '2006-05-23 15:46:49.000000', NULL, 1),
(2450178, 336841, 54816, '<td valign="top">Great!!!! I love it!! <br/>very creative. Congratulations!!!!!</td>', 'Great!!!! I love it!! very creative. Congratulations!!!!!', '2006-05-23 16:08:06.000000', NULL, 1),
(2450204, 336841, 42495, '<td valign="top">Nice macro of something difficult to photograph. I know - I tried it myself!  The border on top and bottom pulls me away a bit from the subject.</td>', 'Nice macro of something difficult to photograph. I know - I tried it myself!  The border on top and bottom pulls me away a bit from the subject.', '2006-05-23 16:23:28.000000', NULL, 1),
